package app.streamnest;
import org.json.*;import java.util.*;
/** Explicit, small owner-visible title/state fields; resume positions and credentials never enter this report. */
final class WatchingPayload {
 static JSONObject clean(JSONObject raw){try{if(raw==null||!Arrays.asList("movies","shows","animes").contains(raw.optString("kind"))||!Arrays.asList("starting","buffering","playing","paused","stopped").contains(raw.optString("state")))return null;String title=raw.optString("title","");if(title.trim().isEmpty()||title.length()>180)return null;for(char ch:title.toCharArray())if(ch<32||ch==127)return null;String lower=title.toLowerCase(Locale.ROOT);if(lower.contains("https://")||lower.contains("http://")||lower.contains("magnet:?")||lower.contains("file://"))return null;for(int i=1;i<title.length()-1;i++)if(Character.isLetter(title.charAt(i-1))&&title.charAt(i)==':'&&(title.charAt(i+1)=='\\'||title.charAt(i+1)=='/'))return null;JSONObject out=new JSONObject().put("title",title.trim()).put("kind",raw.getString("kind")).put("state",raw.getString("state"));if(!raw.getString("kind").equals("movies"))for(String key:new String[]{"season","episode"})if(raw.has(key)){Object n=raw.get(key);if(!(n instanceof Number)||((Number)n).doubleValue()!=((Number)n).longValue()||((Number)n).longValue()<0||((Number)n).longValue()>100000)return null;out.put(key,((Number)n).longValue());}return out;}catch(Exception e){return null;}}
}
